import sys
import sqlite3
from datetime import datetime
import os
from data import DatabaseManager, get_database_path
from goodsprocess import GoodsProcessingTab, GoodsProcessingDialog
from wage import WageCalculationDialog, WageCalculationTab
from PyQt5.QtWidgets import (
    QApplication, QMainWindow, QWidget, QVBoxLayout, QHBoxLayout,
    QLabel, QLineEdit, QPushButton, QTableWidget, QTableWidgetItem,
    QMessageBox, QDialog, QTabWidget, QComboBox, QDateEdit, QHeaderView,
    QTextEdit, QGridLayout, QGroupBox, QSplitter, QFileDialog, QFrame, 
    QCheckBox, QStatusBar, QGraphicsDropShadowEffect
)
from PyQt5.QtCore import Qt, QDate, QTimer, QDateTime
from PyQt5.QtGui import QFont, QColor, QIcon, QPalette

class LoginDialog(QDialog):
    """登录对话框 - 优化版"""

    def __init__(self, db_manager):
        super().__init__()
        self.db_manager = db_manager
        self.user_role = None
        self.username = None
        self.setWindowFlags(Qt.FramelessWindowHint)  # 去掉默认标题栏
        self.setAttribute(Qt.WA_TranslucentBackground)  # 透明背景
        self.init_ui()

    def mousePressEvent(self, event):
        """实现窗口拖动"""
        if event.button() == Qt.LeftButton:
            self.drag_position = event.globalPos() - self.frameGeometry().topLeft()
            event.accept()

    def mouseMoveEvent(self, event):
        """实现窗口拖动"""
        if event.buttons() == Qt.LeftButton:
            self.move(event.globalPos() - self.drag_position)
            event.accept()

    def init_ui(self):
        self.setFixedSize(450, 650)

        # 主布局
        main_layout = QVBoxLayout()
        main_layout.setContentsMargins(0, 0, 0, 0)
        main_layout.setSpacing(0)

        # 创建主容器（带圆角和阴影）- 使用更优雅的渐变
        container = QWidget()
        container.setObjectName("container")
        container.setStyleSheet("""
            QWidget#container {
                background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
                    stop:0 #0f2027, stop:0.5 #203a43, stop:1 #2c5364);
                border-radius: 20px;
            }
        """)

        # 添加阴影效果
        shadow = QGraphicsDropShadowEffect()
        shadow.setBlurRadius(30)
        shadow.setColor(QColor(0, 0, 0, 80))
        shadow.setOffset(0, 5)
        container.setGraphicsEffect(shadow)

        container_layout = QVBoxLayout()
        container_layout.setContentsMargins(25, 25, 25, 25)
        container_layout.setSpacing(15)

        # ========== 顶部装饰区域 ==========
        top_widget = QWidget()
        top_layout = QVBoxLayout()
        top_layout.setContentsMargins(0, 0, 0, 5)
        top_layout.setSpacing(5)

        # 装饰性图标 - 使用金色渐变
        icon_widget = QWidget()
        icon_widget.setFixedSize(70, 70)
        icon_widget.setStyleSheet("""
            QWidget {
                background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
                    stop:0 #f1c40f, stop:1 #e67e22);
                border-radius: 35px;
            }
        """)

        icon_layout = QVBoxLayout()
        factory_icon = QLabel('🏭')
        factory_icon.setFont(QFont('Segoe UI Emoji', 32))
        factory_icon.setAlignment(Qt.AlignCenter)
        factory_icon.setStyleSheet("color: white; background: transparent;")
        icon_layout.addWidget(factory_icon)
        icon_widget.setLayout(icon_layout)

        # 将图标居中
        icon_container = QWidget()
        icon_container_layout = QHBoxLayout()
        icon_container_layout.addStretch()
        icon_container_layout.addWidget(icon_widget)
        icon_container_layout.addStretch()
        icon_container.setLayout(icon_container_layout)

        top_layout.addWidget(icon_container)

        # 主标题 - 使用暖白色
        title = QLabel('向阳厂数据管理系统')
        title.setFont(QFont('Microsoft YaHei', 20, QFont.Bold))
        title.setAlignment(Qt.AlignCenter)
        title.setStyleSheet("color: #ecf0f1; background: transparent; letter-spacing: 2px;")
        top_layout.addWidget(title)

        # 副标题 - 使用柔和的灰色
        subtitle = QLabel('XiangYang Factory Management System')
        subtitle.setFont(QFont('Arial', 9))
        subtitle.setAlignment(Qt.AlignCenter)
        subtitle.setStyleSheet("color: #bdc3c7; background: transparent;")
        top_layout.addWidget(subtitle)

        top_widget.setLayout(top_layout)
        container_layout.addWidget(top_widget)

        # ========== 登录表单区域 ==========
        form_widget = QWidget()
        form_widget.setStyleSheet("""
            QWidget {
                background: rgba(255, 255, 255, 0.05);
                border-radius: 12px;
            }
        """)

        form_layout = QVBoxLayout()
        form_layout.setContentsMargins(25, 20, 25, 20)
        form_layout.setSpacing(15)

        # 用户名标签 - 使用柔和的蓝色
        user_label = QLabel('👤 用户名')
        user_label.setFont(QFont('Microsoft YaHei', 10, QFont.Bold))
        user_label.setStyleSheet("color: #3498db; background: transparent;")
        form_layout.addWidget(user_label)

        # 用户名输入框
        self.user_input = QLineEdit()
        self.user_input.setPlaceholderText('请输入用户名')
        self.user_input.setFixedHeight(40)
        self.user_input.setStyleSheet("""
            QLineEdit {
                background: rgba(255, 255, 255, 0.1);
                border: 2px solid rgba(255, 255, 255, 0.1);
                border-radius: 6px;
                padding: 0 12px;
                color: #ecf0f1;
                font-size: 14px;
            }
            QLineEdit:hover {
                border: 2px solid #3498db;
                background: rgba(255, 255, 255, 0.15);
            }
            QLineEdit:focus {
                border: 2px solid #f1c40f;
                background: rgba(255, 255, 255, 0.2);
            }
            QLineEdit::placeholder {
                color: #95a5a6;
                font-style: italic;
            }
        """)
        form_layout.addWidget(self.user_input)

        # 密码标签 - 使用柔和的橙色
        pwd_label = QLabel('🔒 密码')
        pwd_label.setFont(QFont('Microsoft YaHei', 10, QFont.Bold))
        pwd_label.setStyleSheet("color: #e67e22; background: transparent; margin-top: 5px;")
        form_layout.addWidget(pwd_label)

        # 密码输入框
        self.pwd_input = QLineEdit()
        self.pwd_input.setPlaceholderText('请输入密码')
        self.pwd_input.setEchoMode(QLineEdit.Password)
        self.pwd_input.setFixedHeight(40)
        self.pwd_input.setStyleSheet("""
            QLineEdit {
                background: rgba(255, 255, 255, 0.1);
                border: 2px solid rgba(255, 255, 255, 0.1);
                border-radius: 6px;
                padding: 0 12px;
                color: #ecf0f1;
                font-size: 14px;
            }
            QLineEdit:hover {
                border: 2px solid #e67e22;
                background: rgba(255, 255, 255, 0.15);
            }
            QLineEdit:focus {
                border: 2px solid #f1c40f;
                background: rgba(255, 255, 255, 0.2);
            }
            QLineEdit::placeholder {
                color: #95a5a6;
                font-style: italic;
            }
        """)
        form_layout.addWidget(self.pwd_input)

        # 记住密码选项 - 使用柔和的绿色
        self.remember_check = QCheckBox('记住密码')
        self.remember_check.setStyleSheet("""
            QCheckBox {
                color: #2ecc71;
                font-size: 12px;
                spacing: 5px;
                margin-top: 5px;
            }
            QCheckBox::indicator {
                width: 16px;
                height: 16px;
                border-radius: 3px;
                border: 2px solid #2ecc71;
                background: rgba(255, 255, 255, 0.1);
            }
            QCheckBox::indicator:checked {
                background: #2ecc71;
            }
            QCheckBox::indicator:hover {
                border: 2px solid #f1c40f;
            }
        """)
        form_layout.addWidget(self.remember_check)

        # 按钮区域 - 使用水平布局分开两个按钮
        btn_layout = QHBoxLayout()
        btn_layout.setSpacing(15)
        btn_layout.setContentsMargins(0, 20, 0, 5)

        # 登录按钮 - 使用蓝色渐变
        login_btn = QPushButton('登 录')
        login_btn.setFixedHeight(42)
        login_btn.setCursor(Qt.PointingHandCursor)
        login_btn.setStyleSheet("""
            QPushButton {
                background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
                    stop:0 #3498db, stop:1 #2980b9);
                color: white;
                border: none;
                border-radius: 6px;
                font-size: 15px;
                font-weight: bold;
                letter-spacing: 2px;
            }
            QPushButton:hover {
                background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
                    stop:0 #5dade2, stop:1 #3498db);
            }
            QPushButton:pressed {
                background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
                    stop:0 #2471a3, stop:1 #1f618d);
            }
        """)
        login_btn.clicked.connect(self.login)
        btn_layout.addWidget(login_btn)

        # 取消按钮 - 使用灰色渐变
        cancel_btn = QPushButton('取 消')
        cancel_btn.setFixedHeight(42)
        cancel_btn.setCursor(Qt.PointingHandCursor)
        cancel_btn.setStyleSheet("""
            QPushButton {
                background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
                    stop:0 #7f8c8d, stop:1 #6c7a7d);
                color: white;
                border: none;
                border-radius: 6px;
                font-size: 15px;
                font-weight: bold;
                letter-spacing: 1px;
            }
            QPushButton:hover {
                background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
                    stop:0 #95a5a6, stop:1 #7f8c8d);
            }
            QPushButton:pressed {
                background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
                    stop:0 #5d6d7e, stop:1 #4a5a6b);
            }
        """)
        cancel_btn.clicked.connect(self.reject)
        btn_layout.addWidget(cancel_btn)

        form_layout.addLayout(btn_layout)

        form_widget.setLayout(form_layout)
        container_layout.addWidget(form_widget)

        # ========== 底部提示 ==========
        tip_widget = QWidget()
        tip_widget.setStyleSheet("""
            QWidget {
                background: rgba(0, 0, 0, 0.2);
                border-radius: 8px;
            }
        """)
        tip_layout = QVBoxLayout()
        tip_layout.setContentsMargins(12, 10, 12, 10)
        tip_layout.setSpacing(8)

        tip_title = QLabel('📋 默认测试账号')
        tip_title.setFont(QFont('Microsoft YaHei', 9, QFont.Bold))
        tip_title.setAlignment(Qt.AlignCenter)
        tip_title.setStyleSheet("color: #f1c40f; background: transparent;")
        tip_layout.addWidget(tip_title)

        # 创建账号信息表格样式
        account_frame = QFrame()
        account_frame.setFrameShape(QFrame.NoFrame)
        account_layout = QGridLayout()
        account_layout.setContentsMargins(5, 5, 5, 5)
        account_layout.setSpacing(8)
        account_layout.setHorizontalSpacing(15)

        # 一线工厂账号 - 使用蓝色调
        factory_label = QLabel('🏭 一线工厂:')
        factory_label.setStyleSheet("color: #3498db; font-size: 11px; font-weight: bold;")
        factory_account = QLabel('factory / factory123')
        factory_account.setStyleSheet("color: #bdc3c7; font-size: 11px;")

        # 财务账号 - 使用橙色/红色调
        finance_label = QLabel('💰 财务:')
        finance_label.setStyleSheet("color: #e67e22; font-size: 11px; font-weight: bold;")
        finance_account = QLabel('admin / admin123')
        finance_account.setStyleSheet("color: #bdc3c7; font-size: 11px;")

        # 添加分隔线
        line = QFrame()
